import random
from typing import Final

import pytest

ID_SPACE: Final[int] = 2**63


def make_ids(n: int, seed: int) -> list[int]:
    """Return n distinct ids in [0, ID_SPACE), identical for the same seed.

    Uses a private random.Random(seed) instance, so results do not depend on
    or alter global random state. Performs no I/O and needs no capabilities.

    Raises:
        ValueError: if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    rng = random.Random(seed)
    seen: set[int] = set()
    out: list[int] = []
    while len(out) < n:
        v = rng.randrange(ID_SPACE)
        if v not in seen:
            seen.add(v)
            out.append(v)
    return out


def test_make_ids_length() -> None:
    assert len(make_ids(5, 1)) == 5


def test_make_ids_zero() -> None:
    assert make_ids(0, 1) == []


def test_make_ids_distinct() -> None:
    ids = make_ids(1000, 42)
    assert len(set(ids)) == 1000


def test_make_ids_in_range() -> None:
    for i in make_ids(500, 7):
        assert isinstance(i, int)
        assert 0 <= i < ID_SPACE


def test_make_ids_deterministic_same_seed() -> None:
    assert make_ids(50, 123) == make_ids(50, 123)


def test_make_ids_differs_across_seeds() -> None:
    assert make_ids(50, 1) != make_ids(50, 2)


def test_make_ids_negative_n_raises() -> None:
    with pytest.raises(ValueError):
        make_ids(-1, 0)
